<?php require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$s=db()->prepare("SELECT COUNT(*) total,SUM(status='completed') completed,SUM(status IN('queued','processing')) pending FROM transcripts WHERE user_id=?");$s->execute([Auth::id()]);$stats=$s->fetch();$s=db()->prepare('SELECT id,title,platform,status,created_at FROM transcripts WHERE user_id=? ORDER BY id DESC LIMIT 8');$s->execute([Auth::id()]);$items=$s->fetchAll();$pageTitle='Dashboard';require __DIR__.'/app/views/header.php';?><main class="app-shell"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><div><span class="eyebrow">YOUR WORKSPACE</span><h1 class="h2 fw-bold">Welcome, <?=e(Auth::user()['name'])?></h1></div><a href="#new" class="btn btn-primary">New transcript</a></div><div class="row g-3 mb-4"><?php foreach([['Total transcripts',$stats['total']??0],['Completed',$stats['completed']??0],['In queue',$stats['pending']??0]] as $v):?><div class="col-md-4"><div class="stat-card"><div class="label"><?=e($v[0])?></div><div class="number mt-2"><?= (int)$v[1]?></div></div></div><?php endforeach?></div><div class="row g-4"><div class="col-lg-7"><section id="new" class="panel-card"><h2 class="h5 fw-bold">Create a transcript</h2><p class="small text-secondary">Paste a supported public URL or upload media.</p><form method="post" action="<?=e(url('api/transcripts/create.php'))?>"><?=csrf_field()?><input type="hidden" name="source_type" value="url"><label class="form-label">Video or podcast URL</label><input class="form-control mb-3" type="url" name="url" placeholder="https://www.youtube.com/watch?v=..." required><label class="form-label">Language</label><select class="form-select mb-3" name="language"><option value="auto">Auto detect</option><option value="en">English</option><option value="hi">Hindi</option><option value="gu">Gujarati</option></select><button class="btn btn-primary">Add URL</button></form><hr><h3 class="h6 fw-bold">Upload audio or video</h3><form method="post" enctype="multipart/form-data" action="<?=e(url('api/transcripts/create.php'))?>"><?=csrf_field()?><input type="hidden" name="source_type" value="upload"><div class="drop-zone mb-3" data-drop-zone><i class="fa-solid fa-cloud-arrow-up fs-3 text-primary"></i><p>Choose a file or drop it here</p><small class="text-secondary" data-file-name>No file selected</small><input class="visually-hidden" type="file" id="media_file" name="media_file" accept="audio/*,video/*" required></div><div class="d-flex gap-2"><select class="form-select" name="language"><option value="auto">Auto detect</option><option value="en">English</option><option value="hi">Hindi</option><option value="gu">Gujarati</option></select><button class="btn btn-outline-primary">Upload</button></div></form></section></div><div class="col-lg-5"><section class="panel-card"><div class="d-flex justify-content-between"><h2 class="h5 fw-bold">Recent transcripts</h2><a href="<?=e(url('history.php'))?>">View all</a></div><?php if(!$items):?><p class="text-secondary py-5 text-center">Your transcripts will appear here.</p><?php else:foreach($items as $it):?><a class="d-flex justify-content-between align-items-center py-3 border-bottom text-decoration-none text-reset" href="<?=e(url('transcript.php?id='.$it['id']))?>"><span><strong><?=e($it['title']?:$it['platform'].' transcript')?></strong><small class="d-block text-secondary"><?=e(date('d M Y',strtotime($it['created_at'])))?></small></span><span class="status-pill status-<?=e($it['status'])?>"><?=e($it['status'])?></span></a><?php endforeach;endif?></section></div></div></div></main><?php require __DIR__.'/app/views/footer.php';?>
